// План specs/admin-plans.md, 2.1 (кейс AP-07). Пользователь «בדיקה» (не admin). Только чтение. @prod-safe
// Решение владельца продукта 07.10 (#12126fac): для обычного пользователя админ-панели «нет» —
// прямой заход на /adminpanel перенаправляет на /dashboard, без экрана «Access Denied».
// #12126fac עבר QA 08.10. Мелькание «AdminPanel» в крошках (~0.2–0.4 с) — известный баг #26087e6e, здесь не проверяется.
import { test, expect } from '@playwright/test';
import { setLanguage } from './plans-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Admin Panel — access', () => {
  test('Non-admin opening /adminpanel is redirected to the dashboard, no Access Denied and no plans data #ca557707 #12126fac @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    // Шаг 1: в боковом меню нет «Admin Panel» (ждём загрузки меню по пункту «Jobs»)
    await page.goto('/dashboard');
    await expect(page.getByRole('link', { name: 'Jobs', exact: true })).toBeVisible();
    await expect(page.getByRole('link', { name: 'Admin Panel' })).toHaveCount(0);

    // Шаг 2: прямой переход → перенаправление на главную
    await page.goto('/adminpanel');
    await expect(page).toHaveURL(/\/dashboard(\?|#|$)/, { timeout: 15_000 });
    await expect(page.getByText('Access Denied')).toHaveCount(0);

    // Никаких следов админ-панели
    await expect(page.getByRole('tab', { name: /^(Users|Plans|Funnel)$/ })).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'Assign plan', exact: true })).toHaveCount(0);
    await expect(page.getByText('iamdejar@gmail.com')).toHaveCount(0);
  });
});
